function sharedAncestor(root: TreeNode | null, p: number, q: number): number {
  const parent = new Map<number, TreeNode | null>([[root!.val, null]]);
  const nodeOf = new Map<number, TreeNode>();
  const stack: TreeNode[] = [root!];
  while (stack.length) {
    const n = stack.pop()!;
    nodeOf.set(n.val, n);
    for (const c of [n.left, n.right]) if (c) { parent.set(c.val, n); stack.push(c); }
  }
  const above = new Set<number>();
  for (let n: TreeNode | null = nodeOf.get(p)!; n; n = parent.get(n.val)!) above.add(n.val);
  let n = nodeOf.get(q)!;
  while (!above.has(n.val)) n = parent.get(n.val)!;
  return n.val;
}

