class Solution:
    def sharedAncestor(self, root: Optional[TreeNode], p: int, q: int) -> int:
        parent = {root.val: None}
        stack = [root]
        while stack:
            n = stack.pop()
            for c in (n.left, n.right):
                if c:
                    parent[c.val] = n.val
                    stack.append(c)
        above = set()
        v = p
        while v is not None:
            above.add(v)
            v = parent[v]
        v = q
        while v not in above:
            v = parent[v]
        return v

