function sharedAncestor(root: TreeNode | null, p: number, q: number): number {
  const find = (n: TreeNode | null): TreeNode | null => {
    if (!n || n.val === p || n.val === q) return n; // no need to look below a target
    const l = find(n.left), r = find(n.right);
    if (l && r) return n; // p and q split here
    return l || r;
  };
  return find(root)!.val;
}

